  gita: { n: 'Public domain: Edwin Arnold, The Song Celestial (1885). Modern: Barbara Stoler Miller; Eknath Easwaran; Mahabharata: Van Buitenen, Ganguli (1883–96, public domain).', q: 'Bhagavad Gita Edwin Arnold Song Celestial' },
  yoga: { n: 'Public domain: Swami Vivekananda, Raja Yoga; Sacred Books of the Hindus. Modern: Edwin Bryant; Hatha Yoga Pradipika: Swami Muktibodhananda.', q: 'Yoga Sutras of Patanjali translation' },
  tamil: { n: 'Public domain: G. U. Pope (1886); modern: Blake Wentworth, Tirukkural (Penguin-style editions).', q: 'Tirukkural translation English' },
