  maha: { n: 'Heart / Diamond Sutra: Red Pine; Lotus Sutra: Burton Watson; Public domain: Sacred Books of the East; Bardo Thodol: Gyurme Dorje (Penguin) or W. Y. Evans-Wentz (1927).', q: 'Mahayana sutra translation' },
