const LIB = LIB_RAW.map((s) => { const [id, title, group, when, tr] = s.split('|'); return { id, title, group, when, tr }; });
const LIB_BY_ID = Object.setPrototypeOf(Object.fromEntries(LIB.map((l) => [l.id, l])), null); /* no prototype: an id typed into a web address, such as “constructor”, must not find Object's own members */
/* the imagined shelf: fiction and poetry of the imagination, kept apart from the sources. Whatever draws on the whole Library (search, the random passage and the picker) leaves it out unless it is asked for by name, and whatever shows one of its texts labels it Imagined */
const LIB_IMAGINED_GROUPS = ['im'];
const libImagined = (id) => { const l = LIB_BY_ID[id]; return !!l && LIB_IMAGINED_GROUPS.includes(l.group); };
const libSearchURL = (l) => 'https://duckduckgo.com/?q=' + encodeURIComponent(`${l.title.replace(/\s*\(.*$/, '')} ${(TR[l.tr] || {}).q || ''}`.trim());

if (typeof module !== 'undefined' && module.exports) module.exports = { TR, LIB_GROUPS, MUST_GROUPS, LIB_SHELF_ONLY, LIB_IMAGINED_GROUPS, libImagined, LIB, LIB_BY_ID };
